/**
 * Socket.IO handshake/transport endpoint
 *
 * ## Purpose
 * Realtime Socket.IO transport for dashboard and channel updates.
 *
 * ## Authentication
 * Authenticate with a normal JWT access token using `socket.handshake.auth.token`.
 *
 * ```ts
 * const socket = io("https://api.staging.tragram.app", {
 * path: "/socket.io",
 * auth: { token: accessToken },
 * });
 * ```
 *
 * Handshake auth schema: `WebSocketHandshakeAuth`
 *
 * ## Realtime Contract References
 * - Human-readable realtime docs: `/api/realtime-docs`
 * - Raw AsyncAPI JSON: `/api/realtime-docs.json`
 * - Swagger remains the REST source of truth; AsyncAPI is the authoritative websocket contract reference.
 *
 * ## Client Events
 *
 * | Event | Payload schema | Use it for |
 * | --- | --- | --- |
 * | `account:summary:subscribe` / `account:summary:unsubscribe` | `WebSocketRealtimeSubscribePayload` | Register or stop selected-account summary snapshots. |
 * | `account:checklist:subscribe` / `account:checklist:unsubscribe` | `WebSocketRealtimeSubscribePayload` | Register or stop account checklist snapshots. |
 * | `orders:counts:subscribe` / `orders:counts:unsubscribe` | `WebSocketRealtimeSubscribePayload` | Register or stop selected-account order counts. |
 * | `orders:page:subscribe` / `orders:page:unsubscribe` | `WebSocketOrdersPageSubscribePayload` | Register or stop one selected-account orders page. |
 * | `orders:lifecycle:subscribe` / `orders:lifecycle:unsubscribe` | `WebSocketRealtimeSubscribePayload` | Register or stop selected-account order created/lifecycle updates. |
 * | `symbol:prices:subscribe` / `symbol:prices:unsubscribe` | `WebSocketRealtimeSubscribePayload` | Register or stop symbol price/spec streaming. |
 * | `channel:subscribe` | `WebSocketChannelSubscribePayload` | Register for an initial channel snapshot plus live push updates. |
 * | `channel:unsubscribe` | `WebSocketChannelUnsubscribePayload` | Stop one channel stream or all channel streams. |
 *
 * ## Server Events
 *
 * | Event | Payload schema | What you get |
 * | --- | --- | --- |
 * | `as` | compact account summary | Selected-account broker balance/equity, Tragram-owned closed P&L, and broker floating P&L snapshot. |
 * | `ak` | compact account checklist | Account/setup checklist snapshot. |
 * | `ok` | compact orders counts | Selected-account order counts emitted on subscribe and only when the selected-account count signature changes. |
 * | `opg` | compact orders page | Current subscribed selected-account orders page snapshot. |
 * | `oc` | compact order:created | Selected-account newly created order event with sanitized REST trade/order fields plus optional active-order quote hints. |
 * | `olc` | compact orders lifecycle | Selected-account order lifecycle update/close event with sanitized REST trade/order fields plus optional active-order quote hints for updates. |
 * | `economic-calendar:snapshot` | `WebSocketEconomicCalendarSnapshot` | Complete calendar page snapshot after event content or material provider-health changes. |
 * | `economic-news-guard:snapshot` | `WebSocketEconomicGuardSnapshot` | Complete authenticated-user guard snapshot after a material guard transition. |
 * | `economic-news-settings:snapshot` | `WebSocketEconomicSettingsSnapshot` | Complete authenticated-user settings snapshot after a committed mutation. |
 * | `spt` | `WebSocketSymbolPriceEvent` | Dedicated zero-delay bid/ask tick for active subscribed symbols. |
 * | `ssx` | compact symbol specs | Symbol calculation metadata for newly active subscribed symbols. |
 * | `telegram:catalog-updated` | `WebSocketTelegramCatalogUpdatedEvent` | Authenticated user-scoped catalog invalidation with `catalogVersion`, nullable `requestId`, and `reason`. Clients refetch the bounded REST page. |
 * | `dn` | `WebSocketNotificationCreatedEvent` | Compact new-notification signal (`s: "t"`, optional `m`). |
 * | `cs` | compact channel summary | Channel performance snapshot. |
 * | `co` | compact channel orders | Channel order list snapshot. |
 * | `re` | `WebSocketRealtimeErrorEvent` | Realtime subscription or snapshot failure. |
 * | `ce` | `WebSocketChannelErrorEvent` | Channel subscription failure. |
 *
 * ## Notes
 * - Realtime family subscribe events and `channel:subscribe` must send `rt: 3`; missing `rt`, `rt: 1`, and `rt: 2` fail fast with `re` or `ce`.
 * - The server emits direct compact event names only. The `rt` envelope and verbose server event names are not public websocket outputs.
 * - Live price ticks use `spt` only and are bridged through `WS_SYMBOL_PRICE_EVENTS_CHANNEL` (default `ws:symbol-price-events`). Exact duplicate bid/ask ticks may be suppressed.
 * - Compact timestamps use numeric `ts`. Symbol specs use `ssx`; active `oc` created-order and `olc` updated-order events may include a one-symbol `symbolPrices` quote hint, but no bootstrap price dump is emitted.
 * - Redis bridge traffic is split by stream family: `ws:account-summary-events`, `ws:account-checklist-events`, `ws:orders-counts-events`, `ws:orders-page-events`, `ws:orders-lifecycle-events`, `ws:symbol-price-events`, `ws:notification-events`, and `ws:channel-events`.
 * - `co` snapshots are already server-sorted. Clients should preserve existing row positions for same-order realtime updates and only move rows for genuinely new orders or bucket/status transitions.
 * - Trade rows in `co` include TP progress fields such as `takeProfitTargets`, `closeReason`, and `closeTpLevel`.
 * - `intervalMs` is ignored; websocket streams are push-driven from backend events.
 * - Ownership rule for new websocket events: runtime publisher, AsyncAPI schema, Swagger entry, example payload, and validation test must ship together.
 *
 */
export const getSocketIo = <ThrowOnError extends boolean = false>(options?: Options<GetSocketIoData, ThrowOnError>) => (options?.client ?? client).get<GetSocketIoResponses, GetSocketIoErrors, ThrowOnError>({
    responseType: 'text',
    url: '/socket.io/',
    ...options
});
